ON CONFLICT (facility_code) DO UPDATE SET name = EXCLUDED.name, facility_type = EXCLUDED.facility_type, tier = EXCLUDED.tier, address = EXCLUDED.address, pincode = EXCLUDED.pincode, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, phone = EXCLUDED.phone, website = EXCLUDED.website, ownership = EXCLUDED.ownership, emergency_24x7 = EXCLUDED.emergency_24x7, has_ambulance = EXCLUDED.has_ambulance, has_blood_bank = EXCLUDED.has_blood_bank, has_nicu_level = EXCLUDED.has_nicu_level, notes = EXCLUDED.notes;

